import{_ as t,c as s,o as a,af as i}from"./chunks/framework.DeiWFBFB.js";const k=JSON.parse('{"title":"Client-Side Routing","description":"","frontmatter":{},"headers":[],"relativePath":"api/usage/routing.md","filePath":"api/usage/routing.md","lastUpdated":1753478444000}'),n={name:"api/usage/routing.md"};function o(d,e,h,l,r,p){return a(),s("div",null,e[0]||(e[0]=[i(`<h1 id="client-side-routing" tabindex="-1">Client-Side Routing <a class="header-anchor" href="#client-side-routing" aria-label="Permalink to &quot;Client-Side Routing&quot;">​</a></h1><p>Picard.js contains a client-side router that works by patching the <a href="https://developer.mozilla.org/en-US/docs/Web/API/History_API" target="_blank" rel="noreferrer">HTML5 history API</a>.</p><h2 id="router-events" tabindex="-1">Router Events <a class="header-anchor" href="#router-events" aria-label="Permalink to &quot;Router Events&quot;">​</a></h2><p>Besides the standard <code>popstate</code> some new events have been added. The <code>history</code> element now dispatches the following events at <code>window</code>:</p><table tabindex="0"><thead><tr><th>Name</th><th>Events Arguments</th><th>Description</th></tr></thead><tbody><tr><td><code>popstate</code></td><td><code>PopStateEvent</code> with the provided <code>state</code></td><td>More information <a href="https://developer.mozilla.org/en-US/docs/Web/API/Window/popstate_event" target="_blank" rel="noreferrer">available online</a></td></tr><tr><td><code>pushstate</code></td><td><code>Event</code> with the sender</td><td>Dispatched after <code>pushState</code> has been called</td></tr><tr><td><code>replacestate</code></td><td><code>Event</code> with the sender</td><td>Dispatched after <code>replaceState</code> has been called</td></tr></tbody></table><h2 id="presenting-router-content" tabindex="-1">Presenting Router Content <a class="header-anchor" href="#presenting-router-content" aria-label="Permalink to &quot;Presenting Router Content&quot;">​</a></h2><p>Components may be registered for specific routes using a conventional component name prefixed with <code>page:</code>. For instance, a component that should be displayed at <code>/</code> should be registered with the name <code>page:/</code>.</p><p>The <code>rel=&quot;router&quot;</code> attribute changes a <code>pi-slot</code> web component to listen to the currently active route. It will then sync the <code>name</code> attribute of the <code>pi-slot</code> instance to <code>page:[current-page]</code>, where <code>[current-page]</code> is the path using the history API.</p><p>The following piece of HTML is everything required to display those pages.</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">pi-slot</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;router&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">pi-slot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>A 404 (page not found) content can be shown by introducing a fallback, like for any other <code>pi-slot</code>:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">pi-slot</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;router&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> fallback-template-id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;not-found-page&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">pi-slot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">template</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;not-found-page&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;flex flex-1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Page Not Found&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;The provided page has not been found.&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>There can be multiple <code>pi-slot</code> instances on one page. All would be synced to the current path.</p><h2 id="changing-the-route" tabindex="-1">Changing the Route <a class="header-anchor" href="#changing-the-route" aria-label="Permalink to &quot;Changing the Route&quot;">​</a></h2><p>There are two primary ways to interact with the router:</p><ol><li>By interacting with the HTML5 <code>history</code> object, e.g., <code>history.pushState({}, &#39;&#39;, &#39;/&#39;)</code>.</li><li>By placing standard <code>a</code> elements on the page that have no target (or go to <code>_self</code>) and feature a <em>local</em> <code>href</code> attribute.</li></ol><p>In the second case clicking such anchor tags will be intercepted and the usual (full page) navigation will be aborted. Instead, the HTML5 history API is called and the scroll is reset (i.e., <code>window.scrollTo(0, 0)</code> is called).</p><h2 id="route-parameters" tabindex="-1">Route Parameters <a class="header-anchor" href="#route-parameters" aria-label="Permalink to &quot;Route Parameters&quot;">​</a></h2><p>The register page path can also consider route parameters. As an example, if you want to receive the value of a parameter <code>id</code>, which should be the ID of a product, then a route definition such as <code>/product/:id</code> would be suitable:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>page:/product/:id</span></span></code></pre></div><p>The router also recognizes optional segments. For instance, if a products page can be used with and without a category, you might define a route such:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>page:/products{/:category}?</span></span></code></pre></div><p>This way, you&#39;d receive the <code>category</code> parameter only if it was set. Both paths, <code>/products</code> and <code>/products/foo</code> would be handled by Picard.js.</p><table tabindex="0"><thead><tr><th>Syntax</th><th>Type</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>:id</code></td><td><code>string</code></td><td>A required parameter within a route.</td><td><code>/foo/:id</code></td></tr><tr><td><code>*s</code></td><td><code>string[]</code></td><td>A wildcard parameter taking the remaining segments.</td><td><code>/foo/*splat</code></td></tr><tr><td><code>{opt}</code></td><td><code>string?</code></td><td>An optional segment is enclosed in braces.</td><td><code>/foo{/bar}</code></td></tr></tbody></table>`,24)]))}const g=t(n,[["render",o]]);export{k as __pageData,g as default};
